def test(
    ctx,
    verbose=True,
    color=True,
    capture="sys",
    module=None,
    k=None,
    x=False,
    opts="",
    coverage=False,
    include_slow=False,
    loop_on_fail=False,
):
    """
    Run unit tests via pytest.

    By default, known-slow parts of the suite are SKIPPED unless
    ``--include-slow`` is given.  (Note that ``--include-slow`` does not mesh
    well with explicit ``--opts="-m=xxx"`` - if ``-m`` is found in ``--opts``,
    ``--include-slow`` will be ignored!)
    """
    command = ["pytest"]

    if verbose:
        command.append("-vv")
    if color:
        command.append("--color=yes")
    if capture == "sys":
        command.append("--capture=sys")
    elif capture == "no":
        command.append("--capture=no")

    if module:
        command.append(f"--pyargs={module}")
    if k:
        command.append(f"-k {k}")
    if x:
        command.append("-x")
    if opts:
        command.append(f"--opts={opts}")
    if coverage:
        command.append("--cov")
    if include_slow:
        command.append("--include-slow")
    if loop_on_fail:
        command.append("--looponfail")

    try:
        subprocess.run(command, check=True, shell=True)
    except subprocess.CalledProcessError as e:
        sys.exit(e.returncode)

